{
  "name": "PICA 启动器应用",
  "name_en": "PICA Launcher App",
  "manufacturer": "",
  "description": "这是一个用于实验室计算机的桌面启动工具，用来集中展示并启动 PICA 相关脚本和实用程序，同时提供说明文档、手册、许可证、更新信息、代码仓库链接和脚本目录的访问入口，并带有 GPIB 测试功能。它更像实验软件资源的统一入口，而不是一台物理实验仪器。",
  "description_en": "This is a desktop launcher utility for a laboratory computer that centralizes access to PICA-related scripts and utilities. It provides entry points to documentation, manuals, license information, update notes, repository links, script folders, and a GPIB test function. It is best understood as a lab software launcher rather than a physical instrument.",
  "tag_hints": [
    "script launcher",
    "lab software utility",
    "GPIB test",
    "documentation access",
    "resource browser",
    "experiment automation tools"
  ],
  "actions": [
    {
      "action_name": "auto-create_launcher_panel",
      "description": "创建脚本启动面板。",
      "description_en": "Create the script launcher panel."
    },
    {
      "action_name": "auto-create_resource_panel",
      "description": "创建资源与链接面板。",
      "description_en": "Create the resources and links panel."
    },
    {
      "action_name": "auto-create_widgets",
      "description": "创建应用界面组件。",
      "description_en": "Create the application interface widgets."
    },
    {
      "action_name": "auto-launch_script",
      "description": "启动指定脚本。",
      "description_en": "Launch the specified script."
    },
    {
      "action_name": "auto-log",
      "description": "记录一条日志消息。",
      "description_en": "Log a message."
    },
    {
      "action_name": "auto-open_license",
      "description": "打开许可证信息。",
      "description_en": "Open the license information."
    },
    {
      "action_name": "auto-open_manual_file",
      "description": "打开手册文件。",
      "description_en": "Open the manual file."
    },
    {
      "action_name": "auto-open_readme",
      "description": "打开 README 说明文档。",
      "description_en": "Open the README document."
    },
    {
      "action_name": "auto-open_repo",
      "description": "打开项目代码仓库链接。",
      "description_en": "Open the project repository link."
    },
    {
      "action_name": "auto-open_script_folder",
      "description": "打开指定脚本所在文件夹。",
      "description_en": "Open the folder containing the specified script."
    },
    {
      "action_name": "auto-open_updates",
      "description": "打开更新信息。",
      "description_en": "Open the update information."
    },
    {
      "action_name": "auto-run_gpib_test",
      "description": "运行 GPIB 测试工具。",
      "description_en": "Run the GPIB test utility."
    },
    {
      "action_name": "auto-setup_styles",
      "description": "设置界面样式。",
      "description_en": "Set up the interface styles."
    }
  ]
}

